<?php
function getList(){
$start=1;
$items = $menu->getItems();
/*
* $items=array(
array(
'title'=>'类别名称',
'deeper'=>false,
'shallower'=>false,
'level_diff'=>0
'level'=>2 //缩进等级
)
); */
$lastitem = 0;
if ($items) {
foreach($items as $i => $item)
{
//初始化
$item['deeper'] = false;
$item['shallower'] = false;
$item['level_diff'] = 0;
if (isset($items[$lastitem])) {
$items[$lastitem]['deeper'] = ($item['level'] > $items[$lastitem]['level']); //该类菜单是否有子菜单
$items[$lastitem]['shallower'] = ($item['level'] < $items[$lastitem]['level']); //是否是该级别的最后一个
$items[$lastitem]['level_diff'] = ($items[$lastitem]['level'] - $item['level']); //级别差用来闭合UL和LI的
}
$lastitem= $i;
}
//用来闭合最顶级ROOT标签
if (isset($items[$lastitem])) {
$items[$lastitem]['deeper'] = (($start?$start:1) > $items[$lastitem]['level']);
$items[$lastitem]['shallower'] = (($start?$start:1) < $items[$lastitem]['level']);
$items[$lastitem]['level_diff'] = ($items[$lastitem]['level'] - ($start?$start:1));
}
}
return $items;
}
?>
